body.data:
{
  "aggregate": "question",
  "pipeline": [
    {
      "$match": {}
    },
    {
      "$lookup": {
        "from": "answer",
        "localField": "_id",
        "foreignField": "question_id",
        "as": "answers"
      }
    },
    {
      "$lookup": {
        "from": "bookmark",
        "let": { "questionIdStr": { "$toString": "$_id" } },
        "pipeline": [
          {
            "$match": {
              "$expr": { "$eq": ["$questionId", "$$questionIdStr"] }
            }
          }
        ],
        "as": "bookmarkMatch"
      }
    },
    {
      "$lookup": {
        "from": "appsmith_test",
        "let": { "qIdStr": { "$toString": "$_id" } },
        "pipeline": [
          { "$unwind": "$questions" },
          { 
            "$match": { 
              "$expr": { "$eq": ["$questions._id", "$$qIdStr"] } 
            } 
          },
          { "$count": "occurrenceCount" }
        ],
        "as": "testCountData"
      }
    },
    {
      "$addFields": {
        "isBookmarked": {
          "$gt": [{ "$size": "$bookmarkMatch" }, 0]
        },
        "usageCount": {
          "$ifNull": [{ "$arrayElemAt": ["$testCountData.occurrenceCount", 0] }, 0]
        }
      }
    },
    {
      "$project": {
        "bookmarkMatch": 0,
        "testCountData": 0
      }
    },
    {
      "$match": {{ 
        Select1.selectedOptionValue === "ONLY_ZERO" ? { "usageCount": 0 } : {} 
      }}
    },
    {
      "$sort": {{ 
        (() => {
          let val = Select1.selectedOptionValue;
          if (val === "COUNT_ASC") return { "usageCount": 1 };
          if (val === "COUNT_DESC") return { "usageCount": -1 };

          let wrongVal = Number(appsmith.store.sortByWrong);
          let bookmarkVal = Number(appsmith.store.sortByBookmark);

          if (!isNaN(wrongVal) && wrongVal !== 0) return { "countWrong": wrongVal };
          if (!isNaN(bookmarkVal) && bookmarkVal !== 0) return { "isBookmarked": bookmarkVal };

          return { "_id": 1 };
        })()
      }}
    }
  ],
  "cursor": {
    "batchSize": 5000
  }
}
